function alternates(slug) {
  return `<link rel="alternate" hreflang="en" href="https://www.bespringchem.com/applications/${slug}.html"><link rel="alternate" hreflang="zh-CN" href="https://www.bespringchem.com/zh-cn/applications/${slug}.html"><link rel="alternate" hreflang="zh-TW" href="https://www.bespringchem.com/zh-tw/applications/${slug}.html"><link rel="alternate" hreflang="es" href="https://www.bespringchem.com/es/applications/${slug}.html"><link rel="alternate" hreflang="pt" href="https://www.bespringchem.com/pt/applications/${slug}.html"><link rel="alternate" hreflang="ru" href="https://www.bespringchem.com/ru/applications/${slug}.html"><link rel="alternate" hreflang="de" href="https://www.bespringchem.com/de/applications/${slug}.html"><link rel="alternate" hreflang="ar" href="https://www.bespringchem.com/ar/applications/${slug}.html"><link rel="alternate" hreflang="x-default" href="https://www.bespringchem.com/applications/${slug}.html">`;
}

function renderFaqs(faqs) {
  return faqs.map(([q, a], i) => `<details${i === 0 ? " open" : ""}><summary>${q}</summary><p>${a}</p></details>`).join("");
}

